<?php
namespace Tests\Feature;use App\Models\ActivityType;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;class ActivityTypeTest extends TestCase{    use RefreshDatabase;    protected function setUp(): void    {        parent::setUp();        $this->user = User::factory()->create();        Sanctum::actingAs($this->user, ['*']);        $this->activityTypeData = [            'name' => 'Tipo de Atividade Teste',            'slug' => 'tipo-atividade-teste',            'description' => 'Descrição do tipo de atividade',            'icon' => 'icon-teste',        ];    }    /**     * Teste: listar tipos de atividade com sucesso (index).     */    public function test_list_activity_types_success(): void    {        foreach (range(1, 3) as $i) {            ActivityType::create([                'name' => "Tipo {$i}",                'slug' => "tipo-{$i}",            ]);        }        $response = $this->get('/api/v1/activity-types');        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'status' => 200,        ]);        $response->assertJsonStructure([            'data' => [                'items',                'pagination',            ],            'message',            'status',        ]);    }    /**     * Teste: buscar tipo de atividade por ID com sucesso (show).     */    public function test_show_activity_type_success(): void    {        $activityType = ActivityType::create([            'name' => 'Tipo para Buscar',            'slug' => 'tipo-para-buscar',        ]);        $response = $this->get("/api/v1/activity-types/{$activityType->id}");        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'status' => 200,            'message' => 'Tipo de atividade encontrado.',        ]);        $response->assertJsonStructure([            'data' => [                'id',                'name',                'slug',                'description',                'icon',            ],            'message',            'status',        ]);    }    /**     * Teste: buscar tipo de atividade inexistente retorna 404.     */    public function test_show_activity_type_not_found(): void    {        $response = $this->get('/api/v1/activity-types/99999');        $response->assertStatus(404);        $response->assertJson([            'success' => false,            'status' => 404,        ]);    }    /**     * Teste: criar tipo de atividade com sucesso (store).     */    public function test_store_activity_type_success(): void    {        $response = $this->post('/api/v1/activity-types', $this->activityTypeData);        $response->assertStatus(201);        $response->assertJson([            'success' => true,            'status' => 201,            'message' => 'Tipo de atividade criado com sucesso.',        ]);        $response->assertJsonStructure([            'data' => [                'id',                'name',                'slug',                'description',                'icon',            ],            'message',            'status',        ]);        $this->assertDatabaseHas('activity_types', [            'name' => 'Tipo de Atividade Teste',            'slug' => 'tipo-atividade-teste',        ]);    }    /**     * Teste: criar tipo de atividade com dados inválidos retorna erro de validação.     */    public function test_store_activity_type_validation_error(): void    {        $invalidData = [            'name' => '',            'slug' => '',        ];        $response = $this->post('/api/v1/activity-types', $invalidData);        $response->assertStatus(422);        $response->assertJsonValidationErrors([            'name',        ]);    }    /**     * Teste: atualizar tipo de atividade com sucesso (update).     */    public function test_update_activity_type_success(): void    {        $activityType = ActivityType::create([            'name' => 'Tipo Original',            'slug' => 'tipo-original',        ]);        $updateData = [            'name' => 'Tipo Atualizado',            'slug' => 'tipo-atualizado',        ];        $response = $this->put("/api/v1/activity-types/{$activityType->id}", $updateData);        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'message' => 'Tipo de atividade atualizado com sucesso.',        ]);        $this->assertDatabaseHas('activity_types', [            'id' => $activityType->id,            'name' => 'Tipo Atualizado',        ]);    }    /**     * Teste: atualizar tipo de atividade inexistente retorna 404.     */    public function test_update_activity_type_not_found(): void    {        $response = $this->put('/api/v1/activity-types/99999', [            'name' => 'Novo Nome',        ]);        $response->assertStatus(404);        $response->assertJson([            'success' => false,            'status' => 404,        ]);    }    /**     * Teste: excluir tipo de atividade com sucesso (destroy).     */    public function test_destroy_activity_type_success(): void    {        $activityType = ActivityType::create([            'name' => 'Tipo para Excluir',            'slug' => 'tipo-para-excluir',        ]);        $response = $this->delete("/api/v1/activity-types/{$activityType->id}");        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'message' => 'Tipo de atividade removido com sucesso.',        ]);        $this->assertDatabaseMissing('activity_types', [            'id' => $activityType->id,        ]);    }    /**     * Teste: excluir tipo de atividade inexistente retorna 404.     */    public function test_destroy_activity_type_not_found(): void    {        $response = $this->delete('/api/v1/activity-types/99999');        $response->assertStatus(404);        $response->assertJson([            'success' => false,            'status' => 404,        ]);    }    /**     * Teste: rota sem autenticação retorna 401.     */    public function test_unauthenticated_request_returns_401(): void    {                $this->app['auth']->forgetGuards();

        $response = $this->get('/api/v1/activity-types');        $response->assertStatus(401);    }}